contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 timestamp, uint256 amount) public payable {
        require(amount >= 10 ether);
        require(timestamp > c.pastBlockTime());

        uint256 beforeBalanceC = address(c).balance;
        uint256 beforeBalanceTest = address(this).balance;
        uint256 beforePast = c.pastBlockTime();

        bool reverted;
        try c.call{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPast = c.pastBlockTime();
        uint256 afterBalanceC = address(c).balance;
        uint256 afterBalanceTest = address(this).balance;

        assert(!reverted
            && afterPast == timestamp + 1
            && afterBalanceC == beforeBalanceC + 10 ether - (block.number % 15 == 0 ? beforeBalanceC + 10 ether : 0)
            && afterBalanceTest == beforeBalanceTest - 10 ether + (block.number % 15 == 0 ? beforeBalanceC + 10 ether : 0));
    }

    receive() external payable {}
}

