contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint256 beforePast = c.pastBlockTime();
        uint256 beforeBalanceC = address(c).balance;
        uint256 beforeBalanceTest = address(this).balance;
        uint256 ts = block.timestamp;
        uint256 bn = block.number;

        bool reverted;
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        uint256 afterPast = c.pastBlockTime();
        uint256 afterBalanceC = address(c).balance;
        uint256 afterBalanceTest = address(this).balance;

        bool payment = (bn % 15 == 0);
        bool canSucceed = ts > beforePast;

        bool correct =
            canSucceed
                ? (!reverted
                    && afterPast == ts + 1
                    && (payment
                        ? (afterBalanceC == 0 && afterBalanceTest == beforeBalanceTest + beforeBalanceC)
                        : (afterBalanceC == beforeBalanceC + amount && afterBalanceTest == beforeBalanceTest - amount)))
                : (reverted
                    && afterPast == beforePast
                    && afterBalanceC == beforeBalanceC
                    && afterBalanceTest == beforeBalanceTest);

        assert(correct);
    }

    receive() external payable {}
}

