        // Since we already set it to block.timestamp+1, we cannot succeed. So we need to
        // prove a different general rule.

        // Instead, let's prove: if we call fallback with exactly 10 ether and the requirement
        // block.timestamp > pastBlockTime holds, then after the call the balance of c decreases
        // by 10 ether (unless the block.number % 15 == 0 condition triggers a payout).
        // But we don't know block.number.

        // The accepted rule should be about revert behavior on wrong msg.value. Let's test:
        // A call with msg.value != 10 ether must revert.
        bool reverted;
        uint wrongValue = amount == 10 ether ? 11 ether : amount;
        require(address(this).balance >= wrongValue, "insufficient balance for wrong value");
        try c.fallback{value: wrongValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted || wrongValue == 10 ether);
    }

    receive() external payable {}
}

